<script setup lang="ts">
import { useToast } from '@/composables/useToast'
import {computed,nextTick,onBeforeUnmount,ref,watch} from 'vue'
import {Plus,Search,FileText} from 'lucide-vue-next'
import type {GameNote} from '@/types/game-workspace'
import {errorMessage,formatDateTime} from '@/utils'
import {markdownLines,toggleMarkdownTask} from '@/utils/game-notes'
import GameMarkdown from './GameMarkdown.vue'
import LibraryToolbarMenu from '@/components/library/LibraryToolbarMenu.vue'
const props=defineProps<{gameId:string}>(),emit=defineEmits<{changed:[notes:GameNote[]]}>()
const notes=ref<GameNote[]>([]),selected=ref(''),title=ref(''),body=ref(''),query=ref(''),mode=ref<'edit'|'split'|'preview'>('split'),status=ref(''),failure=ref(''),loading=ref(false),conflict=ref(false)
const editor=ref<HTMLTextAreaElement>(),preview=ref<InstanceType<typeof GameMarkdown>>(),current=computed(()=>notes.value.find(n=>n.id===selected.value))
const visible=computed(()=>notes.value.filter(n=>(n.title+'\n'+n.body).toLowerCase().includes(query.value.toLowerCase())))
let timer:ReturnType<typeof setTimeout>|undefined,inflight:Promise<boolean>|null=null,disposed=false,version=0
const storageKey=(id:string)=>'baoyi-game-note-draft:'+props.gameId+':'+id
function draft(){if(!current.value)return;try{localStorage.setItem(storageKey(current.value.id),JSON.stringify({title:title.value,body:body.value,stamp:current.value.updated_at}))}catch (cause) { useToast().error(errorMessage(cause)) }}
function edited(){version++;if(!conflict.value)failure.value='';status.value='待保存';draft();clearTimeout(timer);timer=setTimeout(()=>void flush(),500)}
async function flush():Promise<boolean>{clearTimeout(timer);if(conflict.value)return false;if(inflight){if(!await inflight)return false;return flush()}const note=current.value;if(!note||note.title===title.value&&note.body===body.value)return true;const captured=version,input={id:note.id,title:title.value,body:body.value,expectedUpdatedAt:note.updated_at};status.value='保存中…'
 inflight=(async()=>{try{const saved=await window.baoyi.game.notes.save(props.gameId,input);const index=notes.value.findIndex(n=>n.id===saved.id);if(index>=0)notes.value[index]=saved;if(captured===version){status.value='已保存';try{localStorage.removeItem(storageKey(note.id))}catch { /* best-effort */ }}emit('changed',notes.value);return true}catch(e){failure.value=errorMessage(e);if(/其他位置|冲突|移除/.test(failure.value))conflict.value=true;status.value='未保存，草稿已保留';return false}})();const result=await inflight;inflight=null;if(result&&captured!==version&&!disposed)return flush();return result
}
async function choose(note:GameNote){if(!await flush())return;selected.value=note.id;title.value=note.title;body.value=note.body;failure.value='';conflict.value=false;status.value='已保存';try{const raw=localStorage.getItem(storageKey(note.id));if(raw){const saved=JSON.parse(raw);if(typeof saved.body==='string'&&typeof saved.title==='string'){title.value=saved.title;body.value=saved.body;status.value='已恢复本地草稿';if(saved.stamp!==note.updated_at){conflict.value=true;failure.value='服务器笔记已有新版本，本地草稿已保留；请先复制草稿，再重新读取核对。'}}}}catch { /* 本地草稿不可读时保留已载入的笔记内容。 */ }version++}
async function load(){loading.value=true;try{const rows=await window.baoyi.game.notes.list(props.gameId);if(disposed)return;notes.value=rows;emit('changed',rows);if(rows[0])await choose(rows[0])}catch(e){failure.value=errorMessage(e)}finally{loading.value=false}}
async function create(template=false){if(!await flush())return;try{const note=await window.baoyi.game.notes.save(props.gameId,{title:template?'游玩进度':'新笔记',body:template?'## 当前进度\n\n\n## 下一步\n\n- [ ] 继续游玩\n\n## 备忘\n':''});notes.value.push(note);await choose(note);emit('changed',notes.value);await nextTick();editor.value?.focus()}catch(e){failure.value=errorMessage(e)}}
async function remove(){if(!current.value||!await flush())return;const note=current.value;if(!window.confirm(`删除笔记「${note.title}」？`))return;try{await window.baoyi.game.notes.remove(props.gameId,note.id,note.updated_at);notes.value=notes.value.filter(n=>n.id!==note.id);selected.value='';title.value='';body.value='';if(notes.value[0])await choose(notes.value[0]);emit('changed',notes.value)}catch(e){failure.value=errorMessage(e)}}
async function reload(){try{if(!window.confirm('重新读取已保存版本？本地草稿请先复制，读取后将保留在浏览器草稿中。'))return;const rows=await window.baoyi.game.notes.list(props.gameId);notes.value=rows;const n=rows.find(n=>n.id===selected.value);if(n){title.value=n.title;body.value=n.body;failure.value='';conflict.value=false;status.value='已重新读取';emit('changed',rows)}}catch(e){failure.value=errorMessage(e)}}
async function copy(){try{await window.baoyi.app.copyText(body.value);status.value='已复制 Markdown'}catch(e){failure.value=errorMessage(e)}}
async function exportNote(){try{if(current.value&&await flush())await window.baoyi.game.notes.export(props.gameId,current.value.id)}catch(e){failure.value=errorMessage(e)}}
function insert(kind:string){const el=editor.value;const start=el?.selectionStart||0,end=el?.selectionEnd||start,chosen=body.value.slice(start,end);const content:Record<string,string>={H2:'## '+(chosen||'章节标题'),B:'**'+(chosen||'粗体')+'**',I:'*'+(chosen||'斜体')+'*',列表:'- '+(chosen||'项目'),待办:'- [ ] '+(chosen||'待办'),引用:'> '+(chosen||'引用'),代码:'`'+(chosen||'代码')+'`',表格:'\n| 项目 | 说明 |\n| --- | --- |\n|  |  |\n'};body.value=body.value.slice(0,start)+content[kind]+body.value.slice(end);edited();void nextTick(()=>{el?.focus();el?.setSelectionRange(start,start+content[kind].length)})}
async function jump(note:GameNote,index:number){if(selected.value!==note.id)await choose(note);if(selected.value!==note.id)return;await nextTick();preview.value?.jump(index);const heading=markdownLines(body.value).headings[index];if(heading&&editor.value){const lines=body.value.split('\n'),start=lines.slice(0,heading.line).join('\n').length+(heading.line?1:0);editor.value.focus();editor.value.setSelectionRange(start,start+lines[heading.line].length);editor.value.scrollTop=Math.max(0,heading.line*23-60)}}
watch(()=>props.gameId,()=>void load(),{immediate:true});onBeforeUnmount(()=>{disposed=true;clearTimeout(timer);draft();void flush()})
defineExpose({flush})
</script>
<template>
 <section class="game-notes" aria-label="游戏笔记"><aside class="notes-nav"><header><label><Search :size="14"/><input v-model="query" aria-label="搜索游戏笔记" placeholder="搜索笔记"/></label><button class="btn btn--icon" aria-label="新建笔记" @click="create()"><Plus :size="16"/></button></header><p v-if="loading">读取笔记中…</p><div v-for="note in visible" :key="note.id" class="note-tree"><button class="note-item" :class="{selected:selected===note.id}" @click="choose(note)"><FileText :size="14"/><span><strong>{{selected===note.id?title:note.title}}</strong><small>{{formatDateTime(note.updated_at)}}</small></span></button><button v-for="(h,i) in markdownLines(selected===note.id?body:note.body).headings" :key="i" class="note-heading" :class="{'level-3':h.level===3}" @click="jump(note,i)">{{h.text}}</button></div></aside>
 <div class="notes-main"><template v-if="current"><header><input v-model="title" aria-label="笔记标题" maxlength="200" @input="edited"/><small role="status">{{status}}</small><div class="mode"><button v-for="(label,key) in {edit:'编辑',split:'分屏',preview:'预览'}" :key="key" :aria-pressed="mode===key" @click="mode=key">{{label}}</button></div><LibraryToolbarMenu icon="more" label="笔记操作"><button @click="copy">复制为 Markdown</button><button @click="exportNote">导出 .md</button><button @click="remove">删除笔记</button></LibraryToolbarMenu></header><p v-if="failure" class="note-error" role="alert">{{failure}}<button @click="copy">复制草稿</button><button @click="reload">重新读取</button></p><div v-if="mode!=='preview'" class="editor-toolbar"><button v-for="label in ['H2','B','I','列表','待办','引用','代码','表格']" :key="label" @click="insert(label)">{{label}}</button></div><div class="note-editors" :class="'mode-'+mode"><textarea v-if="mode!=='preview'" ref="editor" v-model="body" aria-label="Markdown 笔记正文" spellcheck="false" @input="edited"/><div v-if="mode!=='edit'" class="note-preview"><GameMarkdown ref="preview" :text="body" editable-tasks @toggle="body=toggleMarkdownTask(body,$event);edited()"/></div></div></template><div v-else class="notes-empty"><FileText :size="32"/><h3>记下你的游玩进度</h3><p>路线、收集清单、喜欢的段落，都留在这里。</p><button class="btn btn--primary" @click="create()">新建笔记</button><button class="btn btn--subtle" @click="create(true)">从「进度」模板开始</button><p v-if="failure" role="alert">{{failure}}</p></div></div>
 </section>
</template>
<style scoped>
.game-notes{display:flex;height:620px;border-radius:12px;border:1px solid var(--card-border);background:var(--bg-card);overflow:hidden}.notes-nav{width:250px;flex:none;border-right:1px solid var(--divider);overflow:auto;padding:12px}.notes-nav header{display:flex;gap:6px;margin-bottom:12px}.notes-nav label{display:flex;align-items:center;gap:7px;min-width:0;background:var(--bg-main);border-radius:6px;padding:6px 8px;color:var(--text-faint)}.notes-nav input{width:100%;min-width:0;border:0;background:transparent;font-size:12px}.note-item{display:flex;gap:8px;text-align:left;align-items:flex-start;width:100%;padding:10px 8px;border-radius:6px;font-size:12px}.note-item.selected{background:var(--active-surface)}.note-item strong{display:block;overflow-wrap:anywhere;font-weight:500}.note-item small{display:block;font-size:10px;color:var(--text-faint);margin-top:5px}.note-heading{display:block;text-align:left;padding:5px 10px 5px 30px;font-size:11px;color:var(--text-sub);width:100%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.note-heading.level-3{padding-left:42px}.note-heading:hover{background:var(--hover-surface)}.notes-main{min-width:0;flex:1;display:flex;flex-direction:column}.notes-main>header{display:flex;gap:10px;padding:14px 18px;align-items:center;border-bottom:1px solid var(--divider)}.notes-main>header>input{min-width:60px;flex:1;border:0;background:transparent;font-size:15px;font-weight:600}.notes-main>header>small{font-size:10px;color:var(--text-faint)}.mode{display:flex;background:var(--bg-main);padding:2px;border-radius:6px}.mode button{font-size:11px;padding:5px 9px;border-radius:4px;white-space:nowrap;color:var(--text-sub)}.mode [aria-pressed=true]{background:var(--bg-card);color:var(--text-main)}.editor-toolbar{display:flex;gap:4px;padding:7px 14px;border-bottom:1px solid var(--divider)}.editor-toolbar button{font-size:11px;padding:3px 7px;color:var(--text-sub);border-radius:4px}.editor-toolbar button:hover{background:var(--hover-surface)}.note-editors{min-height:0;display:flex;flex:1}.note-editors>textarea,.note-preview{width:50%;min-width:0;overflow:auto;padding:20px;flex:1}.note-editors>textarea{resize:none;border:0;background:var(--bg-main);font:12px/23px var(--font-mono);outline:0}.notes-empty{display:flex;flex:1;align-items:center;justify-content:center;flex-direction:column;gap:14px;color:var(--text-sub)}.notes-empty p{font-size:12px}.note-error{font-size:12px;padding:10px;color:var(--danger)}.note-error button{margin-left:12px;text-decoration:underline}@media(max-width:1050px){.notes-nav{width:200px}.notes-main>header{flex-wrap:wrap}.note-editors.mode-split{flex-direction:column}.note-editors.mode-split>textarea,.mode-split .note-preview{width:100%;min-height:0}}
</style>
